import './styles.css';
import { useState, useEffect } from 'react';

interface NetworkState {
  input: number[];
  hidden: number[];
  output: number;
  target: number;
  error: number;
  weights: {
    ih: number[][];
    ho: number[];
  };
}

const initialState: NetworkState = {
  input: [0.6, 0.4],
  hidden: [0, 0, 0],
  output: 0,
  target: 1.0,
  error: 0,
  weights: {
    ih: [
      [0.5, 0.3, -0.2],
      [0.4, -0.1, 0.6],
    ],
    ho: [0.7, 0.3, 0.5],
  },
};

function relu(x: number): number {
  return Math.max(0, x);
}

function sigmoid(x: number): number {
  return 1 / (1 + Math.exp(-x));
}

function calculateForward(state: NetworkState): NetworkState {
  const hidden = state.weights.ih[0].map((_, j) => {
    const sum = state.input.reduce((acc, inp, i) => acc + inp * state.weights.ih[i][j], 0);
    return relu(sum);
  });

  const outputPre = hidden.reduce((acc, h, i) => acc + h * state.weights.ho[i], 0);
  const output = sigmoid(outputPre);
  const error = Math.pow(state.target - output, 2) / 2;

  return { ...state, hidden, output, error };
}

export default function App() {
  const [state, setState] = useState<NetworkState>(() => calculateForward(initialState));
  const [phase, setPhase] = useState<'forward' | 'error' | 'backward' | 'update'>('forward');
  const [isAnimating, setIsAnimating] = useState(false);
  const [iteration, setIteration] = useState(0);
  const [errorHistory, setErrorHistory] = useState<number[]>([]);

  const learningRate = 0.5;

  const runBackprop = () => {
    if (isAnimating) return;
    setIsAnimating(true);

    // Phase 1: Forward
    setPhase('forward');

    setTimeout(() => {
      // Phase 2: Calculate error
      setPhase('error');

      setTimeout(() => {
        // Phase 3: Backward pass
        setPhase('backward');

        setTimeout(() => {
          // Phase 4: Update weights
          setPhase('update');

          // Calculate gradients and update
          const outputError = state.output - state.target;
          const outputDelta = outputError * state.output * (1 - state.output);

          const newWeightsHO = state.weights.ho.map((w, i) => 
            w - learningRate * outputDelta * state.hidden[i]
          );

          const hiddenDeltas = state.hidden.map((h, i) => {
            if (h <= 0) return 0;
            return outputDelta * state.weights.ho[i];
          });

          const newWeightsIH = state.weights.ih.map((row, i) =>
            row.map((w, j) => w - learningRate * hiddenDeltas[j] * state.input[i])
          );

          const newState = calculateForward({
            ...state,
            weights: { ih: newWeightsIH, ho: newWeightsHO },
          });

          setTimeout(() => {
            setState(newState);
            setErrorHistory(prev => [...prev, newState.error]);
            setIteration(prev => prev + 1);
            setPhase('forward');
            setIsAnimating(false);
          }, 800);

        }, 1000);
      }, 1000);
    }, 800);
  };

  const reset = () => {
    setState(calculateForward(initialState));
    setPhase('forward');
    setIteration(0);
    setErrorHistory([]);
    setIsAnimating(false);
  };

  const setTarget = (val: number) => {
    const newState = calculateForward({ ...state, target: val });
    setState(newState);
  };

  return (
    <div className="app">
      <div className="header">
        <h1>Backprop Visualizer</h1>
        <p className="subtitle">
          Watch how errors flow backward to update weights.
        </p>
      </div>

      <div className="main-display">
        <div className="network-container">
          {/* Input Layer */}
          <div className="layer">
            <div className="layer-label">Input</div>
            {state.input.map((val, i) => (
              <div key={i} className={`node input ${phase === 'forward' ? 'pulse' : ''}`}>
                {val.toFixed(2)}
              </div>
            ))}
          </div>

          {/* Arrows to Hidden */}
          <div className="connections">
            <div className={`arrow ${phase === 'forward' ? 'forward-flow' : ''} ${phase === 'backward' ? 'backward-flow' : ''}`}>
              {phase === 'forward' ? '→' : phase === 'backward' ? '←' : '→'}
            </div>
          </div>

          {/* Hidden Layer */}
          <div className="layer">
            <div className="layer-label">Hidden</div>
            {state.hidden.map((val, i) => (
              <div key={i} className={`node hidden ${phase === 'forward' ? 'pulse' : ''} ${phase === 'backward' ? 'error-pulse' : ''}`}>
                {val.toFixed(2)}
              </div>
            ))}
          </div>

          {/* Arrows to Output */}
          <div className="connections">
            <div className={`arrow ${phase === 'forward' ? 'forward-flow' : ''} ${phase === 'backward' ? 'backward-flow' : ''}`}>
              {phase === 'forward' ? '→' : phase === 'backward' ? '←' : '→'}
            </div>
          </div>

          {/* Output */}
          <div className="layer">
            <div className="layer-label">Output</div>
            <div className={`node output ${phase === 'forward' ? 'pulse' : ''} ${phase === 'error' ? 'error-highlight' : ''}`}>
              {state.output.toFixed(3)}
            </div>
            <div className="target-label">Target: {state.target.toFixed(1)}</div>
          </div>
        </div>

        {/* Error display */}
        <div className={`error-display ${phase === 'error' ? 'highlight' : ''}`}>
          <div className="error-label">Error (Loss)</div>
          <div className="error-value">{state.error.toFixed(4)}</div>
          <div className="error-formula">
            ½(target - output)² = ½({state.target.toFixed(1)} - {state.output.toFixed(3)})²
          </div>
        </div>
      </div>

      <div className="phase-indicator">
        <div className={`phase ${phase === 'forward' ? 'active' : ''}`}>1. Forward</div>
        <div className={`phase ${phase === 'error' ? 'active' : ''}`}>2. Error</div>
        <div className={`phase ${phase === 'backward' ? 'active' : ''}`}>3. Backward</div>
        <div className={`phase ${phase === 'update' ? 'active' : ''}`}>4. Update</div>
      </div>

      <div className="controls">
        <div className="target-control">
          <label>Target Output:</label>
          <input
            type="range"
            min="0"
            max="1"
            step="0.1"
            value={state.target}
            onChange={(e) => setTarget(parseFloat(e.target.value))}
            disabled={isAnimating}
          />
          <span>{state.target.toFixed(1)}</span>
        </div>

        <div className="button-row">
          <button onClick={runBackprop} disabled={isAnimating} className="btn primary">
            {isAnimating ? 'Running...' : 'Run Backprop Step'}
          </button>
          <button onClick={reset} className="btn secondary" disabled={isAnimating}>
            Reset
          </button>
        </div>
      </div>

      <div className="stats-row">
        <div className="stat">
          <span className="stat-value">{iteration}</span>
          <span className="stat-label">Iterations</span>
        </div>
        <div className="stat">
          <span className="stat-value">{state.error.toFixed(4)}</span>
          <span className="stat-label">Current Error</span>
        </div>
        <div className="stat">
          <span className="stat-value">{learningRate}</span>
          <span className="stat-label">Learning Rate</span>
        </div>
      </div>

      {errorHistory.length > 0 && (
        <div className="error-history">
          <h4>Error History</h4>
          <div className="history-bars">
            {errorHistory.slice(-10).map((err, i) => (
              <div key={i} className="history-bar-container">
                <div 
                  className="history-bar" 
                  style={{ height: `${Math.min(100, err * 400)}%` }}
                />
                <span className="bar-label">{(errorHistory.length - 10 + i + 1)}</span>
              </div>
            ))}
          </div>
          <p className="history-note">Each bar shows error after that iteration. Watch it shrink!</p>
        </div>
      )}

      <div className="insight-box">
        <h3>What's Happening</h3>
        <p>
          <strong>Forward:</strong> Data flows input → output, making a prediction.
        </p>
        <p>
          <strong>Error:</strong> We measure how wrong the prediction was.
        </p>
        <p>
          <strong>Backward:</strong> The error signal flows backward, computing how much each weight contributed.
        </p>
        <p>
          <strong>Update:</strong> Each weight is nudged to reduce the error next time.
        </p>
      </div>
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: linear-gradient(135deg, #dc2626 0%, #9333ea 100%);
  min-height: 100vh;
  padding: 1.5rem 1rem;
}

.app {
  max-width: 800px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 1.5rem;
}

h1 {
  color: white;
  font-size: 1.75rem;
  margin-bottom: 0.5rem;
}

.subtitle {
  color: rgba(255, 255, 255, 0.85);
  font-size: 0.95rem;
}

.main-display {
  background: white;
  border-radius: 1rem;
  padding: 1.5rem;
  margin-bottom: 1rem;
}

.network-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
}

.layer {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
}

.layer-label {
  font-size: 0.75rem;
  color: #6b7280;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.node {
  width: 55px;
  height: 55px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  font-size: 0.8rem;
  border: 3px solid;
  transition: all 0.3s;
}

.node.input {
  background: #dbeafe;
  border-color: #3b82f6;
  color: #1e40af;
}

.node.hidden {
  background: #f3e8ff;
  border-color: #8b5cf6;
  color: #5b21b6;
}

.node.output {
  background: #dcfce7;
  border-color: #22c55e;
  color: #166534;
}

.node.pulse {
  animation: pulse 0.6s ease-out;
}

.node.error-pulse {
  animation: errorPulse 0.6s ease-out;
  border-color: #ef4444;
}

.node.error-highlight {
  border-color: #ef4444;
  box-shadow: 0 0 15px rgba(239, 68, 68, 0.5);
}

@keyframes pulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.15); box-shadow: 0 0 20px rgba(99, 102, 241, 0.5); }
  100% { transform: scale(1); }
}

@keyframes errorPulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.15); box-shadow: 0 0 20px rgba(239, 68, 68, 0.5); }
  100% { transform: scale(1); }
}

.connections {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.arrow {
  font-size: 2rem;
  color: #d1d5db;
  transition: all 0.3s;
}

.arrow.forward-flow {
  color: #22c55e;
  animation: flowRight 0.5s ease-out;
}

.arrow.backward-flow {
  color: #ef4444;
  animation: flowLeft 0.5s ease-out;
}

@keyframes flowRight {
  0% { transform: translateX(-10px); opacity: 0; }
  100% { transform: translateX(0); opacity: 1; }
}

@keyframes flowLeft {
  0% { transform: translateX(10px); opacity: 0; }
  100% { transform: translateX(0); opacity: 1; }
}

.target-label {
  font-size: 0.75rem;
  color: #6b7280;
  margin-top: 0.25rem;
}

.error-display {
  background: #fef2f2;
  border: 2px solid #fecaca;
  border-radius: 0.75rem;
  padding: 1rem;
  text-align: center;
  transition: all 0.3s;
}

.error-display.highlight {
  border-color: #ef4444;
  box-shadow: 0 0 20px rgba(239, 68, 68, 0.3);
}

.error-label {
  font-size: 0.8rem;
  color: #991b1b;
  margin-bottom: 0.25rem;
}

.error-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: #dc2626;
}

.error-formula {
  font-size: 0.75rem;
  color: #6b7280;
  margin-top: 0.5rem;
  font-family: monospace;
}

.phase-indicator {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

.phase {
  padding: 0.5rem 1rem;
  background: rgba(255, 255, 255, 0.2);
  border-radius: 2rem;
  font-size: 0.8rem;
  color: rgba(255, 255, 255, 0.7);
  transition: all 0.3s;
}

.phase.active {
  background: white;
  color: #374151;
  font-weight: 600;
}

.controls {
  background: white;
  border-radius: 1rem;
  padding: 1.25rem;
  margin-bottom: 1rem;
}

.target-control {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-bottom: 1rem;
}

.target-control label {
  font-size: 0.9rem;
  color: #374151;
}

.target-control input[type="range"] {
  flex: 1;
  accent-color: #8b5cf6;
}

.target-control span {
  font-weight: 600;
  min-width: 40px;
}

.button-row {
  display: flex;
  gap: 0.75rem;
}

.btn {
  flex: 1;
  padding: 0.75rem 1.5rem;
  border: none;
  border-radius: 0.5rem;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}

.btn.primary {
  background: linear-gradient(135deg, #dc2626, #9333ea);
  color: white;
}

.btn.primary:hover:not(:disabled) {
  opacity: 0.9;
}

.btn.secondary {
  background: #f3f4f6;
  color: #374151;
}

.btn.secondary:hover:not(:disabled) {
  background: #e5e7eb;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.stats-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.stat {
  background: rgba(255, 255, 255, 0.15);
  border-radius: 0.75rem;
  padding: 1rem;
  text-align: center;
}

.stat-value {
  display: block;
  font-size: 1.25rem;
  font-weight: 700;
  color: white;
}

.stat-label {
  font-size: 0.75rem;
  color: rgba(255, 255, 255, 0.8);
}

.error-history {
  background: white;
  border-radius: 1rem;
  padding: 1.25rem;
  margin-bottom: 1rem;
}

.error-history h4 {
  font-size: 0.9rem;
  color: #374151;
  margin-bottom: 0.75rem;
}

.history-bars {
  display: flex;
  align-items: flex-end;
  gap: 0.5rem;
  height: 80px;
  padding: 0.5rem;
  background: #f9fafb;
  border-radius: 0.5rem;
}

.history-bar-container {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  height: 100%;
}

.history-bar {
  width: 100%;
  background: linear-gradient(180deg, #ef4444, #f97316);
  border-radius: 0.25rem 0.25rem 0 0;
  transition: height 0.3s;
  margin-top: auto;
}

.bar-label {
  font-size: 0.65rem;
  color: #9ca3af;
  margin-top: 0.25rem;
}

.history-note {
  font-size: 0.8rem;
  color: #6b7280;
  margin-top: 0.5rem;
  text-align: center;
}

.insight-box {
  background: rgba(255, 255, 255, 0.95);
  border-radius: 1rem;
  padding: 1.25rem;
}

.insight-box h3 {
  color: #1f2937;
  font-size: 1rem;
  margin-bottom: 0.75rem;
}

.insight-box p {
  color: #4b5563;
  font-size: 0.85rem;
  line-height: 1.5;
  margin-bottom: 0.5rem;
}

.insight-box p:last-child {
  margin-bottom: 0;
}

@media (max-width: 600px) {
  .network-container {
    flex-wrap: wrap;
    gap: 1rem;
  }

  .node {
    width: 45px;
    height: 45px;
    font-size: 0.7rem;
  }

  .phase-indicator {
    flex-wrap: wrap;
  }
}
